/**
 * dodo-webhook — Edge Function
 *
 * Handles incoming Dodo Payments webhook events and keeps the profiles table
 * in sync with subscription state.
 *
 * Handled events:
 *   subscription.active          → activate plan, set scan_limit, billing_cycle_end
 *   subscription.renewed         → update billing_cycle_end
 *   subscription.cancelled       → downgrade to free, clear billing data
 *   subscription.on_hold         → log for observability
 *   payment.failed               → log for observability
 *   subscription.charge_failed   → log for observability
 *
 * Required env vars:
 *   DODO_WEBHOOK_SECRET          (from Dodo Payments dashboard → webhook endpoint)
 *   DODO_PRODUCT_PRO_MONTHLY
 *   DODO_PRODUCT_PRO_ANNUAL
 *   DODO_PRODUCT_AGENCY_MONTHLY
 *   DODO_PRODUCT_AGENCY_ANNUAL
 *   SUPABASE_URL
 *   SUPABASE_SERVICE_ROLE_KEY
 *
 * Security: Webhook signature is verified via standardwebhooks before any processing.
 */

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { Webhook } from "https://esm.sh/standardwebhooks@1.0.0";

// ── Plan config ───────────────────────────────────────────────────

type PlanType = "free" | "pro" | "agency";

const PLAN_LIMITS: Record<PlanType, number> = {
  free: 3,
  pro: 50,
  agency: 500,
};

function getPlanFromProductId(productId: string): PlanType {
  const proMonthly = Deno.env.get("DODO_PRODUCT_PRO_MONTHLY");
  const proAnnual = Deno.env.get("DODO_PRODUCT_PRO_ANNUAL");
  const agencyMonthly = Deno.env.get("DODO_PRODUCT_AGENCY_MONTHLY");
  const agencyAnnual = Deno.env.get("DODO_PRODUCT_AGENCY_ANNUAL");

  if (productId === proMonthly || productId === proAnnual) return "pro";
  if (productId === agencyMonthly || productId === agencyAnnual) return "agency";

  console.warn(`Unknown product ID: ${productId}. Defaulting to 'pro'.`);
  return "pro";
}

// ── Serve ─────────────────────────────────────────────────────────

serve(async (req: Request) => {
  const body = await req.text();

  const webhookSecret = Deno.env.get("DODO_WEBHOOK_SECRET");
  if (!webhookSecret) {
    console.error("DODO_WEBHOOK_SECRET env var not set");
    return new Response(
      JSON.stringify({ error: "Webhook secret not configured" }),
      { status: 500, headers: { "Content-Type": "application/json" } }
    );
  }

  // ── Verify signature (standardwebhooks) ──────────────────────────
  let event: { type: string; data: Record<string, unknown> };

  try {
    const wh = new Webhook(webhookSecret);
    const headers = {
      "webhook-id": req.headers.get("webhook-id") ?? "",
      "webhook-timestamp": req.headers.get("webhook-timestamp") ?? "",
      "webhook-signature": req.headers.get("webhook-signature") ?? "",
    };
    event = wh.verify(body, headers) as { type: string; data: Record<string, unknown> };
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : "Invalid signature";
    console.error("Webhook signature verification failed:", message);
    return new Response(
      JSON.stringify({ error: `Webhook verification failed: ${message}` }),
      { status: 400, headers: { "Content-Type": "application/json" } }
    );
  }

  // ── Admin Supabase client (bypasses RLS) ─────────────────────────
  const supabase = createClient(
    Deno.env.get("SUPABASE_URL") ?? "",
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? ""
  );

  // ── Event routing ─────────────────────────────────────────────────
  try {
    switch (event.type) {
      // ── subscription.active ──────────────────────────────────────
      // Fires when a new subscription is created and payment succeeds.
      case "subscription.active": {
        const sub = event.data as {
          subscription_id: string;
          customer_id: string;
          product_id: string;
          current_period_end?: number;
          metadata?: Record<string, string>;
        };

        const userId = sub.metadata?.user_id;
        const plan = (sub.metadata?.plan ?? getPlanFromProductId(sub.product_id)) as PlanType;

        if (!userId) {
          console.error("subscription.active: missing user_id in metadata");
          break;
        }

        const billingCycleEnd = sub.current_period_end
          ? new Date(sub.current_period_end * 1000).toISOString()
          : null;

        const { error } = await supabase
          .from("profiles")
          .update({
            plan,
            scan_limit: PLAN_LIMITS[plan] ?? PLAN_LIMITS.pro,
            dodo_subscription_id: sub.subscription_id,
            dodo_customer_id: sub.customer_id,
            billing_cycle_end: billingCycleEnd,
            updated_at: new Date().toISOString(),
          })
          .eq("id", userId);

        if (error) {
          console.error("subscription.active profile update error:", error);
        } else {
          console.log(`Activated ${plan} plan for user ${userId}`);
        }
        break;
      }

      // ── subscription.renewed ─────────────────────────────────────
      // Fires on each successful renewal cycle.
      case "subscription.renewed": {
        const sub = event.data as {
          subscription_id: string;
          customer_id: string;
          product_id: string;
          current_period_end?: number;
        };

        const { data: profile, error: profileError } = await supabase
          .from("profiles")
          .select("id, plan")
          .eq("dodo_customer_id", sub.customer_id)
          .single();

        if (profileError || !profile) {
          console.error(
            "subscription.renewed: profile not found for customer",
            sub.customer_id
          );
          break;
        }

        const billingCycleEnd = sub.current_period_end
          ? new Date(sub.current_period_end * 1000).toISOString()
          : null;

        const { error } = await supabase
          .from("profiles")
          .update({
            dodo_subscription_id: sub.subscription_id,
            billing_cycle_end: billingCycleEnd,
            updated_at: new Date().toISOString(),
          })
          .eq("id", profile.id);

        if (error) {
          console.error("subscription.renewed profile update error:", error);
        } else {
          console.log(`Renewed subscription for user ${profile.id}`);
        }
        break;
      }

      // ── subscription.cancelled ───────────────────────────────────
      // Fires when a subscription is cancelled (immediately or at period end).
      case "subscription.cancelled": {
        const sub = event.data as {
          subscription_id: string;
          customer_id: string;
        };

        const { data: profile, error: profileError } = await supabase
          .from("profiles")
          .select("id")
          .eq("dodo_customer_id", sub.customer_id)
          .single();

        if (profileError || !profile) {
          console.error(
            "subscription.cancelled: profile not found for customer",
            sub.customer_id
          );
          break;
        }

        const { error } = await supabase
          .from("profiles")
          .update({
            plan: "free",
            scan_limit: PLAN_LIMITS.free,
            dodo_subscription_id: null,
            billing_cycle_end: null,
            updated_at: new Date().toISOString(),
          })
          .eq("id", profile.id);

        if (error) {
          console.error("subscription.cancelled profile update error:", error);
        } else {
          console.log(`Downgraded user ${profile.id} to free plan (subscription cancelled)`);
        }
        break;
      }

      // ── subscription.on_hold / payment.failed ────────────────────
      case "subscription.on_hold":
      case "payment.failed":
      case "subscription.charge_failed": {
        const data = event.data as {
          customer_id?: string;
          subscription_id?: string;
        };
        console.log(
          `${event.type} for customer ${data.customer_id ?? "unknown"}, subscription ${data.subscription_id ?? "unknown"}`
        );
        // Future: trigger a dunning email via send-email function
        break;
      }

      default:
        console.log(`Unhandled webhook event type: ${event.type}`);
    }

    return new Response(
      JSON.stringify({ received: true }),
      { status: 200, headers: { "Content-Type": "application/json" } }
    );
  } catch (error: unknown) {
    const message = error instanceof Error ? error.message : "Handler error";
    console.error(`Error handling ${event.type}:`, error);
    return new Response(
      JSON.stringify({ error: message }),
      { status: 500, headers: { "Content-Type": "application/json" } }
    );
  }
});

