/**
 * dodo-portal — Edge Function
 *
 * Creates a Dodo Payments Customer Portal session so users can manage
 * their subscription, payment method, and download invoices.
 *
 * Returns:
 *   { url: string } — Dodo-hosted portal URL
 *
 * Required env vars:
 *   DODO_API_KEY
 *   SUPABASE_URL
 *   SUPABASE_ANON_KEY
 *   SUPABASE_SERVICE_ROLE_KEY
 */

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type",
};

serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  try {
    // ── 1. Auth ────────────────────────────────────────────────────
    const authHeader = req.headers.get("Authorization");
    if (!authHeader) {
      return new Response(
        JSON.stringify({ error: "Missing Authorization header" }),
        { status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    const supabaseUser = createClient(
      Deno.env.get("SUPABASE_URL") ?? "",
      Deno.env.get("SUPABASE_ANON_KEY") ?? "",
      { global: { headers: { Authorization: authHeader } } }
    );

    const { data: { user }, error: userError } = await supabaseUser.auth.getUser();
    if (userError || !user) {
      return new Response(
        JSON.stringify({ error: "Unauthorized" }),
        { status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // ── 2. Get profile and dodo_customer_id ────────────────────────
    const supabaseAdmin = createClient(
      Deno.env.get("SUPABASE_URL") ?? "",
      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? ""
    );

    const { data: profile, error: profileError } = await supabaseAdmin
      .from("profiles")
      .select("dodo_customer_id")
      .eq("id", user.id)
      .single();

    if (profileError || !profile?.dodo_customer_id) {
      return new Response(
        JSON.stringify({
          error: "No active subscription found. Please upgrade to a paid plan first.",
        }),
        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // ── 3. Fetch Dodo Customer Portal URL ──────────────────────────
    const dodoApiKey = Deno.env.get("DODO_API_KEY") ?? "";

    const portalRes = await fetch(
      `https://api.dodopayments.com/customers/${profile.dodo_customer_id}/portal`,
      {
        method: "GET",
        headers: {
          "Authorization": `Bearer ${dodoApiKey}`,
        },
      }
    );

    if (!portalRes.ok) {
      const errText = await portalRes.text();
      console.error("Dodo portal API error:", portalRes.status, errText);
      return new Response(
        JSON.stringify({ error: "Failed to create billing portal session." }),
        { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    const portalData = await portalRes.json();
    const portalUrl = portalData.link ?? portalData.url;

    if (!portalUrl) {
      console.error("No portal URL in Dodo response:", portalData);
      return new Response(
        JSON.stringify({ error: "No portal URL returned from payment provider." }),
        { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    return new Response(
      JSON.stringify({ url: portalUrl }),
      { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  } catch (error: unknown) {
    const message = error instanceof Error ? error.message : "Internal server error";
    console.error("dodo-portal error:", error);
    return new Response(
      JSON.stringify({ error: message }),
      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  }
});

