1	/**
2	 * send-email — Edge Function
3	 *
4	 * Sends transactional emails via Resend (HTTP, no SDK — Deno compatible).
5	 *
6	 * Accepted request body shapes:
7	 *   { type: 'welcome';        to: string; data: { name: string } }
8	 *   { type: 'scan_complete';  to: string; data: { name: string; url: string; score: number; scan_id: string; critical_count: number; quick_wins: number } }
9	 *   { type: 'weekly_digest';  to: string; data: { name: string; scans_this_week: number; avg_score: number } }
10	 *
11	 * Required env vars:
12	 *   RESEND_API_KEY — Resend secret key
13	 *   APP_URL        — e.g. https://app.convertscan.com (no trailing slash)
14	 */
15	
16	import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
17	
18	// ── CORS ──────────────────────────────────────────────────────────
19	
20	const corsHeaders = {
21	  "Access-Control-Allow-Origin": "*",
22	  "Access-Control-Allow-Headers":
23	    "authorization, x-client-info, apikey, content-type",
24	  "Access-Control-Allow-Methods": "POST, OPTIONS",
25	};
26	
27	function jsonResponse(body: unknown, status = 200): Response {
28	  return new Response(JSON.stringify(body), {
29	    status,
30	    headers: { ...corsHeaders, "Content-Type": "application/json" },
31	  });
32	}
33	
34	// ── Brand constants ───────────────────────────────────────────────
35	
36	const BRAND_COLOR = "#6366F1"; // indigo-500
37	const BRAND_NAME = "ConvertScan";
38	const FROM_ADDRESS = `${BRAND_NAME} <noreply@convertscan.com>`;
39	
40	// ── Shared email layout helpers ───────────────────────────────────
41	
42	function emailWrapper(content: string): string {
43	  return `<!DOCTYPE html>
44	<html lang="en">
45	<head>
46	  <meta charset="UTF-8" />
47	  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
48	  <title>${BRAND_NAME}</title>
49	</head>
50	<body style="margin:0;padding:0;background:#F8FAFC;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Helvetica,Arial,sans-serif;">
51	  <table width="100%" cellpadding="0" cellspacing="0" style="background:#F8FAFC;padding:32px 16px;">
52	    <tr>
53	      <td align="center">
54	        <table width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;">
55	
56	          <!-- Header -->
57	          <tr>
58	            <td style="background:${BRAND_COLOR};border-radius:12px 12px 0 0;padding:24px 32px;">
59	              <p style="margin:0;font-size:20px;font-weight:700;color:#FFFFFF;letter-spacing:-0.3px;">${BRAND_NAME}</p>
60	              <p style="margin:4px 0 0;font-size:11px;color:rgba(255,255,255,0.7);letter-spacing:0.5px;text-transform:uppercase;">CRO Audit Platform</p>
61	            </td>
62	          </tr>
63	
64	          <!-- Body -->
65	          <tr>
66	            <td style="background:#FFFFFF;padding:36px 32px;border-left:1px solid #E2E8F0;border-right:1px solid #E2E8F0;">
67	              ${content}
68	            </td>
69	          </tr>
70	
71	          <!-- Footer -->
72	          <tr>
73	            <td style="background:#F1F5F9;border-radius:0 0 12px 12px;border:1px solid #E2E8F0;border-top:0;padding:20px 32px;">
74	              <p style="margin:0;font-size:12px;color:#94A3B8;line-height:1.6;">
75	                You received this email because you have an account at ${BRAND_NAME}.
76	                <br />
77	                &copy; ${new Date().getFullYear()} ${BRAND_NAME}. All rights reserved.
78	                <br />
79	                <a href="{{UNSUBSCRIBE_URL}}" style="color:#6366F1;text-decoration:none;">Unsubscribe</a> &nbsp;·&nbsp;
80	                <a href="https://convertscan.com/privacy" style="color:#6366F1;text-decoration:none;">Privacy Policy</a>
81	              </p>
82	            </td>
83	          </tr>
84	
85	        </table>
86	      </td>
87	    </tr>
88	  </table>
89	</body>
90	</html>`;
91	}
92	
93	function ctaButton(label: string, href: string): string {
94	  return `<table cellpadding="0" cellspacing="0" style="margin:28px 0;">
95	    <tr>
96	      <td style="background:${BRAND_COLOR};border-radius:8px;">
97	        <a href="${href}"
98	           style="display:inline-block;padding:14px 28px;font-size:15px;font-weight:600;color:#FFFFFF;text-decoration:none;letter-spacing:-0.1px;">
99	          ${label}
100	        </a>
101	      </td>
102	    </tr>
103	  </table>`;
104	}
105	
106	function scoreChip(score: number): string {
107	  const color = score >= 70 ? "#22C55E" : score >= 40 ? "#F59E0B" : "#EF4444";
108	  const label = score >= 85 ? "Excellent" : score >= 70 ? "Good" : score >= 55 ? "Average" : score >= 40 ? "Below Average" : "Poor";
109	  return `<span style="display:inline-block;background:${color};color:#fff;font-size:22px;font-weight:700;padding:8px 18px;border-radius:10px;letter-spacing:-0.5px;">
110	    ${score}<span style="font-size:13px;opacity:0.85;">/100</span>
111	  </span>
112	  <span style="display:inline-block;background:${color}18;color:${color};font-size:13px;font-weight:600;padding:6px 12px;border-radius:6px;margin-left:10px;vertical-align:middle;">
113	    ${label}
114	  </span>`;
115	}
116	
117	// ── Template builders ─────────────────────────────────────────────
118	
119	interface WelcomeData {
120	  name: string;
121	}
122	
123	function buildWelcomeEmail(to: string, data: WelcomeData, appUrl: string): { subject: string; html: string } {
124	  const firstName = data.name.split(" ")[0];
125	  const html = emailWrapper(`
126	    <h1 style="margin:0 0 8px;font-size:26px;font-weight:700;color:#0F172A;letter-spacing:-0.5px;">
127	      Welcome to ${BRAND_NAME}, ${firstName}!
