135	        <td style="padding:0 20px;">
136	          <p style="margin:0 0 16px;font-size:13px;font-weight:700;color:#475569;text-transform:uppercase;letter-spacing:0.5px;">What you get with ${BRAND_NAME}</p>
137	          ${["CRO score across 7 conversion pillars", "AI-powered recommendations with rewritten copy", "Benchmark comparison against industry averages", "Quick wins sorted by impact and effort"].map((item) => `
138	          <p style="margin:0 0 10px;font-size:14px;color:#334155;padding-left:20px;position:relative;">
139	            <span style="position:absolute;left:0;color:${BRAND_COLOR};font-weight:700;">✓</span>
140	            ${item}
141	          </p>`).join("")}
142	        </td>
143	      </tr>
144	    </table>
145	
146	    ${ctaButton("Scan Your First Page →", `${appUrl}/scan`)}
147	
148	    <p style="margin:20px 0 0;font-size:13px;color:#94A3B8;line-height:1.6;">
149	      Have questions? Reply to this email — we read and respond to every message.
150	    </p>
151	  `);
152	
153	  return {
154	    subject: `Welcome to ${BRAND_NAME} — let's boost your conversions`,
155	    html,
156	  };
157	}
158	
159	interface ScanCompleteData {
160	  name: string;
161	  url: string;
162	  score: number;
163	  scan_id: string;
164	  critical_count: number;
165	  quick_wins: number;
166	}
167	
168	function buildScanCompleteEmail(to: string, data: ScanCompleteData, appUrl: string): { subject: string; html: string } {
169	  const firstName = data.name.split(" ")[0];
170	  const reportUrl = `${appUrl}/reports/${data.scan_id}`;
171	  const displayUrl = data.url.replace(/^https?:\/\//, "").replace(/\/$/, "");
172	
173	  const html = emailWrapper(`
174	    <p style="margin:0 0 6px;font-size:14px;color:#64748B;">Hi ${firstName},</p>
175	    <h1 style="margin:0 0 4px;font-size:24px;font-weight:700;color:#0F172A;letter-spacing:-0.5px;">
