233	function buildWeeklyDigestEmail(to: string, data: WeeklyDigestData, appUrl: string): { subject: string; html: string } {
234	  const firstName = data.name.split(" ")[0];
235	
236	  const html = emailWrapper(`
237	    <p style="margin:0 0 6px;font-size:14px;color:#64748B;">Hi ${firstName},</p>
