267	
268	// ── Request types ─────────────────────────────────────────────────
269	
270	type EmailRequest =
271	  | { type: "welcome"; to: string; data: WelcomeData }
272	  | { type: "scan_complete"; to: string; data: ScanCompleteData }
273	  | { type: "weekly_digest"; to: string; data: WeeklyDigestData };
274	
275	// ── Resend call ───────────────────────────────────────────────────
276	
277	async function sendViaResend(
278	  to: string,
279	  subject: string,
280	  html: string,
281	): Promise<void> {
282	  const apiKey = Deno.env.get("RESEND_API_KEY");
283	  if (!apiKey) {
284	    throw new Error("RESEND_API_KEY env var is not set");
285	  }
286	
287	  const res = await fetch("https://api.resend.com/emails", {
288	    method: "POST",
289	    headers: {
290	      "Authorization": `Bearer ${apiKey}`,
291	      "Content-Type": "application/json",
292	    },
293	    body: JSON.stringify({
294	      from: FROM_ADDRESS,
295	      to,
296	      subject,
297	      html,
298	    }),
299	  });
