/**
 * send-email — Edge Function
 *
 * Sends transactional emails via Resend (HTTP, no SDK — Deno compatible).
 *
 * Accepted request body shapes:
 *   { type: 'welcome';        to: string; data: { name: string } }
 *   { type: 'scan_complete';  to: string; data: { name: string; url: string; score: number; scan_id: string; critical_count: number; quick_wins: number } }
 *   { type: 'weekly_digest';  to: string; data: { name: string; scans_this_week: number; avg_score: number } }
 *
 * Required env vars:
 *   RESEND_API_KEY — Resend secret key
 *   APP_URL        — e.g. https://app.convertscan.com (no trailing slash)
 */

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";

// ── CORS ──────────────────────────────────────────────────────────

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

function jsonResponse(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
}

// ── Brand constants ───────────────────────────────────────────────

const BRAND_COLOR = "#6366F1"; // indigo-500
const BRAND_NAME = "ConvertScan";
const FROM_ADDRESS = `${BRAND_NAME} <noreply@convertscan.com>`;

// ── Shared email layout helpers ───────────────────────────────────

function emailWrapper(content: string): string {
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>${BRAND_NAME}</title>
</head>
<body style="margin:0;padding:0;background:#F8FAFC;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Helvetica,Arial,sans-serif;">
  <table width="100%" cellpadding="0" cellspacing="0" style="background:#F8FAFC;padding:32px 16px;">
    <tr>
      <td align="center">
        <table width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;">

          <!-- Header -->
          <tr>
            <td style="background:${BRAND_COLOR};border-radius:12px 12px 0 0;padding:24px 32px;">
              <p style="margin:0;font-size:20px;font-weight:700;color:#FFFFFF;letter-spacing:-0.3px;">${BRAND_NAME}</p>
              <p style="margin:4px 0 0;font-size:11px;color:rgba(255,255,255,0.7);letter-spacing:0.5px;text-transform:uppercase;">CRO Audit Platform</p>
            </td>
          </tr>

          <!-- Body -->
          <tr>
            <td style="background:#FFFFFF;padding:36px 32px;border-left:1px solid #E2E8F0;border-right:1px solid #E2E8F0;">
              ${content}
            </td>
          </tr>

          <!-- Footer -->
          <tr>
            <td style="background:#F1F5F9;border-radius:0 0 12px 12px;border:1px solid #E2E8F0;border-top:0;padding:20px 32px;">
              <p style="margin:0;font-size:12px;color:#94A3B8;line-height:1.6;">
                You received this email because you have an account at ${BRAND_NAME}.
                <br />
                &copy; ${new Date().getFullYear()} ${BRAND_NAME}. All rights reserved.
                <br />
                <a href="{{UNSUBSCRIBE_URL}}" style="color:#6366F1;text-decoration:none;">Unsubscribe</a> &nbsp;·&nbsp;
                <a href="https://convertscan.com/privacy" style="color:#6366F1;text-decoration:none;">Privacy Policy</a>
              </p>
            </td>
          </tr>

        </table>
      </td>
    </tr>
  </table>
</body>
</html>`;
}

function ctaButton(label: string, href: string): string {
  return `<table cellpadding="0" cellspacing="0" style="margin:28px 0;">
    <tr>
      <td style="background:${BRAND_COLOR};border-radius:8px;">
        <a href="${href}"
           style="display:inline-block;padding:14px 28px;font-size:15px;font-weight:600;color:#FFFFFF;text-decoration:none;letter-spacing:-0.1px;">
          ${label}
        </a>
      </td>
    </tr>
  </table>`;
}

function scoreChip(score: number): string {
  const color = score >= 70 ? "#22C55E" : score >= 40 ? "#F59E0B" : "#EF4444";
  const label = score >= 85 ? "Excellent" : score >= 70 ? "Good" : score >= 55 ? "Average" : score >= 40 ? "Below Average" : "Poor";
  return `<span style="display:inline-block;background:${color};color:#fff;font-size:22px;font-weight:700;padding:8px 18px;border-radius:10px;letter-spacing:-0.5px;">
    ${score}<span style="font-size:13px;opacity:0.85;">/100</span>
  </span>
  <span style="display:inline-block;background:${color}18;color:${color};font-size:13px;font-weight:600;padding:6px 12px;border-radius:6px;margin-left:10px;vertical-align:middle;">
    ${label}
  </span>`;
}

// ── Template builders ─────────────────────────────────────────────

interface WelcomeData {
  name: string;
}

function buildWelcomeEmail(to: string, data: WelcomeData, appUrl: string): { subject: string; html: string } {
  const firstName = data.name.split(" ")[0];
  const html = emailWrapper(`
    <h1 style="margin:0 0 8px;font-size:26px;font-weight:700;color:#0F172A;letter-spacing:-0.5px;">
      Welcome to ${BRAND_NAME}, ${firstName}!
    </h1>
    <p style="margin:0 0 20px;font-size:15px;color:#64748B;line-height:1.6;">
      Your account is ready. You're one scan away from discovering exactly what's costing you conversions.
    </p>

    <table width="100%" cellpadding="0" cellspacing="0" style="background:#F8FAFC;border:1px solid #E2E8F0;border-radius:10px;padding:20px;margin-bottom:24px;">
      <tr>
        <td style="padding:0 20px;">
          <p style="margin:0 0 16px;font-size:13px;font-weight:700;color:#475569;text-transform:uppercase;letter-spacing:0.5px;">What you get with ${BRAND_NAME}</p>
          ${["CRO score across 7 conversion pillars", "AI-powered recommendations with rewritten copy", "Benchmark comparison against industry averages", "Quick wins sorted by impact and effort"].map((item) => `
          <p style="margin:0 0 10px;font-size:14px;color:#334155;padding-left:20px;position:relative;">
            <span style="position:absolute;left:0;color:${BRAND_COLOR};font-weight:700;">✓</span>
            ${item}
          </p>`).join("")}
        </td>
      </tr>
    </table>

    ${ctaButton("Scan Your First Page →", `${appUrl}/scan`)}

    <p style="margin:20px 0 0;font-size:13px;color:#94A3B8;line-height:1.6;">
      Have questions? Reply to this email — we read and respond to every message.
    </p>
  `);

  return {
    subject: `Welcome to ${BRAND_NAME} — let's boost your conversions`,
    html,
  };
}

interface ScanCompleteData {
  name: string;
  url: string;
  score: number;
  scan_id: string;
  critical_count: number;
  quick_wins: number;
}

function buildScanCompleteEmail(to: string, data: ScanCompleteData, appUrl: string): { subject: string; html: string } {
  const firstName = data.name.split(" ")[0];
  const reportUrl = `${appUrl}/reports/${data.scan_id}`;
  const displayUrl = data.url.replace(/^https?:\/\//, "").replace(/\/$/, "");

  const html = emailWrapper(`
    <p style="margin:0 0 6px;font-size:14px;color:#64748B;">Hi ${firstName},</p>
    <h1 style="margin:0 0 4px;font-size:24px;font-weight:700;color:#0F172A;letter-spacing:-0.5px;">
      Your CRO audit is ready.
    </h1>
    <p style="margin:0 0 24px;font-size:14px;color:#94A3B8;word-break:break-all;">${displayUrl}</p>

    <!-- Score block -->
    <table width="100%" cellpadding="0" cellspacing="0" style="background:#F8FAFC;border:1px solid #E2E8F0;border-radius:10px;margin-bottom:24px;">
      <tr>
        <td style="padding:24px 24px 20px;">
          <p style="margin:0 0 12px;font-size:12px;font-weight:700;color:#94A3B8;text-transform:uppercase;letter-spacing:0.5px;">Overall CRO Score</p>
          ${scoreChip(data.score)}
        </td>
      </tr>
      <tr>
        <td style="padding:0 24px 20px;">
          <table width="100%" cellpadding="0" cellspacing="0">
            <tr>
              <td width="50%" style="padding-right:8px;">
                <div style="background:#FEF2F2;border-radius:8px;padding:14px 16px;">
                  <p style="margin:0;font-size:22px;font-weight:700;color:#EF4444;">${data.critical_count}</p>
                  <p style="margin:4px 0 0;font-size:12px;color:#94A3B8;">Critical Issues</p>
                </div>
              </td>
              <td width="50%" style="padding-left:8px;">
                <div style="background:#F0FDF4;border-radius:8px;padding:14px 16px;">
                  <p style="margin:0;font-size:22px;font-weight:700;color:#22C55E;">${data.quick_wins}</p>
                  <p style="margin:4px 0 0;font-size:12px;color:#94A3B8;">Quick Wins Available</p>
                </div>
              </td>
            </tr>
          </table>
        </td>
      </tr>
    </table>

    <p style="margin:0 0 8px;font-size:14px;color:#334155;line-height:1.6;">
      Your full report includes AI-powered recommendations, pillar breakdowns, and a prioritized fix list — all waiting for you.
    </p>

    ${ctaButton("View Full Report →", reportUrl)}

    <p style="margin:16px 0 0;font-size:12px;color:#94A3B8;line-height:1.6;">
      This report link is private to your account. Download a PDF copy from the report page.
    </p>
  `);

  return {
    subject: `Your CRO audit is ready — Score: ${data.score}/100`,
    html,
  };
}

interface WeeklyDigestData {
  name: string;
  scans_this_week: number;
  avg_score: number;
}

function buildWeeklyDigestEmail(to: string, data: WeeklyDigestData, appUrl: string): { subject: string; html: string } {
  const firstName = data.name.split(" ")[0];

  const html = emailWrapper(`
    <p style="margin:0 0 6px;font-size:14px;color:#64748B;">Hi ${firstName},</p>
    <h1 style="margin:0 0 16px;font-size:24px;font-weight:700;color:#0F172A;letter-spacing:-0.5px;">
      Your weekly CRO summary
    </h1>

    <table width="100%" cellpadding="0" cellspacing="0" style="background:#F8FAFC;border:1px solid #E2E8F0;border-radius:10px;margin-bottom:24px;">
      <tr>
        <td width="50%" style="padding:20px 24px;border-right:1px solid #E2E8F0;">
          <p style="margin:0;font-size:28px;font-weight:700;color:#0F172A;">${data.scans_this_week}</p>
          <p style="margin:4px 0 0;font-size:13px;color:#94A3B8;">Scans this week</p>
        </td>
        <td width="50%" style="padding:20px 24px;">
          <p style="margin:0;font-size:28px;font-weight:700;color:#0F172A;">${data.avg_score}<span style="font-size:14px;color:#94A3B8;">/100</span></p>
          <p style="margin:4px 0 0;font-size:13px;color:#94A3B8;">Average score</p>
        </td>
      </tr>
    </table>

    <p style="margin:0 0 20px;font-size:14px;color:#334155;line-height:1.6;">
      Keep scanning regularly — tracking your score over time is the best way to measure CRO progress.
    </p>

    ${ctaButton("Go to Dashboard →", `${appUrl}/dashboard`)}
  `);

  return {
    subject: `Your weekly CRO digest — ${data.scans_this_week} scan${data.scans_this_week !== 1 ? "s" : ""} this week`,
    html,
  };
}

// ── Request types ─────────────────────────────────────────────────

type EmailRequest =
  | { type: "welcome"; to: string; data: WelcomeData }
  | { type: "scan_complete"; to: string; data: ScanCompleteData }
  | { type: "weekly_digest"; to: string; data: WeeklyDigestData };

// ── Resend call ───────────────────────────────────────────────────

async function sendViaResend(
  to: string,
  subject: string,
  html: string,
): Promise<void> {
  const apiKey = Deno.env.get("RESEND_API_KEY");
  if (!apiKey) {
    throw new Error("RESEND_API_KEY env var is not set");
  }

  const res = await fetch("https://api.resend.com/emails", {
    method: "POST",
    headers: {
      "Authorization": `Bearer ${apiKey}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      from: FROM_ADDRESS,
      to,
      subject,
      html,
    }),
  });

  if (!res.ok) {
    const body = await res.text();
    throw new Error(`Resend API error ${res.status}: ${body.slice(0, 300)}`);
  }
}

// ── Main handler ──────────────────────────────────────────────────

serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  if (req.method !== "POST") {
    return jsonResponse({ error: "Method not allowed" }, 405);
  }

  const appUrl = Deno.env.get("APP_URL") ?? "https://app.convertscan.com";

  let payload: EmailRequest;
  try {
    payload = await req.json() as EmailRequest;
  } catch {
    return jsonResponse({ error: "Invalid JSON body" }, 400);
  }

  if (!payload.type || !payload.to) {
    return jsonResponse({ error: "type and to are required" }, 400);
  }

  let subject: string;
  let html: string;

  try {
    switch (payload.type) {
      case "welcome": {
        const result = buildWelcomeEmail(payload.to, payload.data, appUrl);
        subject = result.subject;
        html = result.html;
        break;
      }
      case "scan_complete": {
        const result = buildScanCompleteEmail(payload.to, payload.data, appUrl);
        subject = result.subject;
        html = result.html;
        break;
      }
      case "weekly_digest": {
        const result = buildWeeklyDigestEmail(payload.to, payload.data, appUrl);
        subject = result.subject;
        html = result.html;
        break;
      }
      default: {
        return jsonResponse({ error: `Unknown email type: ${(payload as { type: string }).type}` }, 400);
      }
    }
  } catch (err) {
    console.error("Email template build failed:", err);
    return jsonResponse({ error: "Failed to build email template" }, 500);
  }

  try {
    await sendViaResend(payload.to, subject, html);
    return jsonResponse({ status: "sent", type: payload.type, to: payload.to });
  } catch (err) {
    console.error("Resend delivery failed:", err);
    return jsonResponse(
      { error: "Email delivery failed", detail: err instanceof Error ? err.message : "unknown" },
      500,
    );
  }
});

