import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";
import supabase from "@/lib/supabase";
import { useAuth } from "@/contexts/AuthContext";
import type { Scan, PageType } from "@/types";
import type { ScanRow } from "@/types/database";

// ── Query keys ──────────────────────────────────────────────────

export const scanKeys = {
  all: ["scans"] as const,
  lists: () => [...scanKeys.all, "list"] as const,
  list: (userId: string) => [...scanKeys.lists(), userId] as const,
  details: () => [...scanKeys.all, "detail"] as const,
  detail: (id: string) => [...scanKeys.details(), id] as const,
};

// ── Row → App type mapper ───────────────────────────────────────

function rowToScan(row: ScanRow): Scan {
  return {
    id: row.id,
    user_id: row.user_id,
    url: row.url,
    favicon_url: row.favicon_url,
    page_title: row.page_title,
    page_type: row.page_type,
    status: row.status,
    overall_score: row.overall_score,
    issues_found: row.issues_found,
    critical_issues: row.critical_issues,
    warnings: row.warnings,
    quick_wins: row.quick_wins,
    screenshot_url: row.screenshot_url,
    device: row.device,
    created_at: row.created_at,
    completed_at: row.completed_at,
  };
}

// ── useScans ────────────────────────────────────────────────────

export function useScans() {
  const { user } = useAuth();

  return useQuery({
    queryKey: scanKeys.list(user?.id ?? ""),
    queryFn: async (): Promise<Scan[]> => {
      if (!user?.id) return [];

      const { data, error } = await supabase
        .from("scans")
        .select("*")
        .eq("user_id", user.id)
        .order("created_at", { ascending: false });

      if (error) throw new Error(error.message);
      return (data as ScanRow[]).map(rowToScan);
    },
    enabled: !!user?.id,
    staleTime: 1000 * 30, // 30 seconds
  });
}

// ── useScan ─────────────────────────────────────────────────────

export function useScan(id: string | undefined, options?: { refetchInterval?: number | false }) {
  const { user } = useAuth();

  return useQuery({
    queryKey: scanKeys.detail(id ?? ""),
    queryFn: async (): Promise<Scan | null> => {
      if (!id || !user?.id) return null;

      const { data, error } = await supabase
        .from("scans")
        .select("*")
        .eq("id", id)
        .eq("user_id", user.id)
        .single();

      if (error) {
        if (error.code === "PGRST116") return null;
        throw new Error(error.message);
      }

      return rowToScan(data as ScanRow);
    },
    enabled: !!id && !!user?.id,
    refetchInterval: options?.refetchInterval,
    staleTime: 0,
  });
}

// ── useCreateScan ───────────────────────────────────────────────

interface CreateScanInput {
  url: string;
  page_type: PageType;
}

export function useCreateScan() {
  const { user, refreshProfile } = useAuth();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async ({ url, page_type }: CreateScanInput): Promise<Scan> => {
      if (!user?.id) throw new Error("Not authenticated");

      // Insert the scan row first
      const { data: scanData, error: insertError } = await supabase
        .from("scans")
        .insert({
          user_id: user.id,
          url,
          page_type,
          status: "pending" as const,
        })
        .select("*")
        .single();

      if (insertError) throw new Error(insertError.message);

      const scan = rowToScan(scanData as ScanRow);

      // Invoke edge function — fire and don't block the return
      // The edge function updates the scan row when done
      supabase.functions
        .invoke("analyze-url", {
          body: { scan_id: scan.id, url, page_type },
        })
        .catch((err: unknown) => {
          console.error("Edge function invocation failed:", err);
          toast.error("Analysis engine failed to start. Please try re-scanning in a moment.", { duration: 6000 });
        });

      return scan;
    },
    onSuccess: (data) => {
      if (!user?.id) return;
      // Optimistically prepend the new scan to the list cache
      queryClient.setQueryData<Scan[]>(scanKeys.list(user.id), (prev) =>
        prev ? [data, ...prev] : [data]
      );
      // Prime the detail cache
      queryClient.setQueryData(scanKeys.detail(data.id), data);
      // Refresh profile to show updated scans_used count
      refreshProfile();
    },
  });
}

// ── useDeleteScan ───────────────────────────────────────────────

export function useDeleteScan() {
  const { user } = useAuth();
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (scanId: string): Promise<void> => {
      if (!user?.id) throw new Error("Not authenticated");

      const { error } = await supabase
        .from("scans")
        .delete()
        .eq("id", scanId)
        .eq("user_id", user.id);

      if (error) throw new Error(error.message);
    },
    onSuccess: (_data, scanId) => {
      if (!user?.id) return;
      // Remove from list cache
      queryClient.setQueryData<Scan[]>(scanKeys.list(user.id), (prev) =>
        prev ? prev.filter((s) => s.id !== scanId) : []
      );
      // Remove detail cache
      queryClient.removeQueries({ queryKey: scanKeys.detail(scanId) });
    },
  });
}

// ── useRefreshScan ──────────────────────────────────────────────
// Creates a new scan for the same URL/page_type as an existing scan

export function useRefreshScan() {
  const createScan = useCreateScan();

  return useMutation({
    mutationFn: async (sourceScan: Pick<Scan, "url" | "page_type">): Promise<Scan> => {
      return createScan.mutateAsync({ url: sourceScan.url, page_type: sourceScan.page_type });
    },
  });
}

