async function devFallbackCapture(url: string): Promise<ScreenshotServiceResponse> {
  const accessKey = Deno.env.get("SCREENSHOTONE_ACCESS_KEY");

  let screenshotBase64 = "";
  if (accessKey) {
    try {
      // ScreenshotOne free tier — returns base64 image
      const params = new URLSearchParams({
        access_key: accessKey,
        url,
        full_page: "true",
        viewport_width: "1280",
        viewport_height: "900",
        format: "jpg",
        image_quality: "80",
        response_type: "json",
      });
      const ssRes = await fetch(
        `https://api.screenshotone.com/take?${params.toString()}`,
      );
      if (ssRes.ok) {
        const ssJson = await ssRes.json();
        screenshotBase64 = ssJson.screenshot ?? "";
      }
    } catch (e) {
      console.warn("ScreenshotOne fallback failed:", e);
    }
  }

  // Fetch raw HTML for DOM scraping
  const domData = await scrapeDomFromHtml(url);

  return {
    screenshot_base64: screenshotBase64,
    dom_data: domData.domData,
    page_title: domData.pageTitle,
    favicon_url: domData.faviconUrl,
  };
}

// ── Lightweight HTML scraper (dev fallback) ───────────────────

async function scrapeDomFromHtml(url: string): Promise<{
  domData: DomData;
  pageTitle: string;
  faviconUrl: string;
}> {
  let html = "";
  try {
    const res = await fetch(url, {
      headers: {
        "User-Agent":
          "Mozilla/5.0 (compatible; CROBOT/1.0; +https://convertscn.com)",
        "Accept": "text/html,application/xhtml+xml",
      },
      signal: AbortSignal.timeout(15_000),
    });
    if (res.ok) {
      html = await res.text();
    }
  } catch (e) {
    console.warn("HTML fetch failed:", e);
    // Return empty DOM — AI will flag missing data as findings
  }

  return parseHtml(html, url);
}

function parseHtml(
  html: string,
  baseUrl: string,
): { domData: DomData; pageTitle: string; faviconUrl: string } {
  // Extract title
  const titleMatch = html.match(/<title[^>]*>([^<]+)<\/title>/i);
  const pageTitle = titleMatch ? decodeHtmlEntities(titleMatch[1].trim()) : "";

  // Extract favicon
  const faviconMatch = html.match(
    /<link[^>]+rel=["'](?:shortcut )?icon["'][^>]+href=["']([^"']+)["']/i,
  ) ?? html.match(/<link[^>]+href=["']([^"']+)["'][^>]+rel=["'](?:shortcut )?icon["']/i);
  let faviconUrl = "";
  if (faviconMatch) {
    try {
      faviconUrl = new URL(faviconMatch[1], baseUrl).toString();
    } catch (_) {
      faviconUrl = faviconMatch[1];
    }
  }

  // Extract meta description
  const metaMatch = html.match(
    /<meta[^>]+name=["']description["'][^>]+content=["']([^"']+)["']/i,
  ) ?? html.match(
    /<meta[^>]+content=["']([^"']+)["'][^>]+name=["']description["']/i,
  );
  const metaDescription = metaMatch ? decodeHtmlEntities(metaMatch[1]) : "";

  // Extract headings h1-h4
  const headings: string[] = [];
  const headingRegex = /<h([1-4])[^>]*>([\s\S]*?)<\/h\1>/gi;
  let hMatch;
  while ((hMatch = headingRegex.exec(html)) !== null && headings.length < 20) {
    const text = stripTags(hMatch[2]).trim();
    if (text) headings.push(text);
  }

  // Extract buttons and links with CTA-like text
  const ctaButtons: string[] = [];
  const ctaKeywords = /\b(get|start|try|sign|join|buy|shop|order|book|schedule|download|learn|see|watch|explore|discover|request|contact|subscribe)\b/i;
  const buttonRegex = /<(?:button|a)[^>]*>([\s\S]*?)<\/(?:button|a)>/gi;
  let btnMatch;
  while ((btnMatch = buttonRegex.exec(html)) !== null && ctaButtons.length < 15) {
    const text = stripTags(btnMatch[1]).trim();
    if (text && text.length < 60 && ctaKeywords.test(text)) {
      ctaButtons.push(text);
    }
  }

  // Extract images
  const images: Array<{ src: string; alt: string }> = [];
  const imgRegex = /<img[^>]+>/gi;
  let imgMatch;
  while ((imgMatch = imgRegex.exec(html)) !== null && images.length < 20) {
    const srcMatch = imgMatch[0].match(/src=["']([^"']+)["']/i);
    const altMatch = imgMatch[0].match(/alt=["']([^"']*)["']/i);
    if (srcMatch) {
      images.push({
        src: srcMatch[1],
        alt: altMatch ? altMatch[1] : "",
      });
    }
  }

  // Extract links
  const links: Array<{ text: string; href: string }> = [];
  const linkRegex = /<a[^>]+href=["']([^"'#][^"']*)["'][^>]*>([\s\S]*?)<\/a>/gi;
  let linkMatch;
  while ((linkMatch = linkRegex.exec(html)) !== null && links.length < 30) {
    const text = stripTags(linkMatch[2]).trim();
    if (text && text.length < 80) {
      links.push({ text, href: linkMatch[1] });
    }
  }

  // Count forms
  const forms = (html.match(/<form[^>]*>/gi) ?? []).length;

  // Heuristic: extract testimonial-like text blocks (blockquote or q tags)
  const testimonials: string[] = [];
  const quoteRegex = /<(?:blockquote|q)[^>]*>([\s\S]*?)<\/(?:blockquote|q)>/gi;
  let qMatch;
  while ((qMatch = quoteRegex.exec(html)) !== null && testimonials.length < 5) {
    const text = stripTags(qMatch[1]).trim();
    if (text && text.length > 30) testimonials.push(text.slice(0, 300));
  }

  // Extract body text (strip scripts, styles, nav, footer first)
  let bodyText = html
    .replace(/<script[\s\S]*?<\/script>/gi, "")
    .replace(/<style[\s\S]*?<\/style>/gi, "")
    .replace(/<nav[\s\S]*?<\/nav>/gi, "")
    .replace(/<footer[\s\S]*?<\/footer>/gi, "")
    .replace(/<header[\s\S]*?<\/header>/gi, "");
  bodyText = stripTags(bodyText).replace(/\s+/g, " ").trim();

  // Detect trust badges from common keywords
  const trustBadges: string[] = [];
  const badgeKeywords = [
    "SSL", "GDPR", "SOC 2", "ISO", "PCI", "HIPAA", "BBB",
    "Trustpilot", "G2", "Capterra", "Product Hunt", "4.8", "4.9", "5.0",
    "money-back guarantee", "100% satisfaction", "secure checkout",
    "verified", "certified", "award",
  ];
  for (const kw of badgeKeywords) {
    if (html.toLowerCase().includes(kw.toLowerCase())) {
      trustBadges.push(kw);
    }
  }

  return {
    domData: {
      headings,
      cta_buttons: ctaButtons,
      images,
      meta_description: metaDescription,
      body_text: bodyText,
      links,
      forms,
      testimonials,
      trust_badges: trustBadges,
    },
    pageTitle,

content.content:
