function buildPageSpeedFallback(): PageSpeedResult {
  return {
    score: 65,
    findings: [
      buildPerfFinding(
        "f_pp_fallback",
        "PageSpeed data unavailable — using estimated score",
        "info",
        "Google PageSpeed Insights API was not available during this scan. Performance score is estimated at 65/100 (industry average).",
        "Configure PAGESPEED_API_KEY to enable real PageSpeed analysis in future scans.",
        "Add your Google Cloud API key as PAGESPEED_API_KEY in Supabase Edge Function secrets.",
        false,
        "quick",
        "0%",
        "Technical",
      ),
    ],
  };
}

// ── AI Response Parsers ───────────────────────────────────────

function extractJsonFromText(text: string): string {
  // Strip markdown code blocks if present
  const codeBlockMatch = text.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (codeBlockMatch) return codeBlockMatch[1].trim();

  // Find first { and last }
  const start = text.indexOf("{");
  const end = text.lastIndexOf("}");
  if (start !== -1 && end !== -1 && end > start) {
    return text.slice(start, end + 1);
  }

  return text.trim();
}

function parseAndSanitizeVisionResult(rawText: string): VisionAnalysisResult {
  let parsed: Record<string, unknown>;
  try {
    parsed = JSON.parse(extractJsonFromText(rawText));
  } catch (_e) {
    console.error("Failed to parse vision AI response:", rawText.slice(0, 500));
    // Return safe defaults
    return buildDefaultVisionResult();
  }

  return {
    visual_hierarchy: sanitizePillarResult(
      parsed.visual_hierarchy as Record<string, unknown>,
      "vh",
    ),
    cta_effectiveness: sanitizePillarResult(
      parsed.cta_effectiveness as Record<string, unknown>,
      "ct",
    ),
    trust_signals: sanitizePillarResult(
      parsed.trust_signals as Record<string, unknown>,
      "ts",
    ),
    mobile_experience: sanitizePillarResult(
      parsed.mobile_experience as Record<string, unknown>,
      "me",
    ),
  };
}

function parseAndSanitizeTextResult(rawText: string): TextAnalysisResult {
  let parsed: Record<string, unknown>;
  try {
    parsed = JSON.parse(extractJsonFromText(rawText));
  } catch (_e) {
    console.error("Failed to parse text AI response:", rawText.slice(0, 500));
    return buildDefaultTextResult();
  }

  return {
    value_proposition: sanitizePillarResult(
      parsed.value_proposition as Record<string, unknown>,
      "vp",
    ),
    content_copy: sanitizePillarResult(
      parsed.content_copy as Record<string, unknown>,
      "cc",
    ),
    cta_effectiveness: parsed.cta_effectiveness
      ? sanitizePillarResult(
          parsed.cta_effectiveness as Record<string, unknown>,
          "ct_copy",
        )
      : undefined,
  };
}

function sanitizePillarResult(
  raw: Record<string, unknown> | undefined,
  prefix: string,
): { score: number; findings: Finding[] } {
  if (!raw || typeof raw !== "object") {
    return { score: 50, findings: [] };
  }

  const score = typeof raw.score === "number"
    ? Math.max(0, Math.min(100, Math.round(raw.score)))
    : 50;

  const rawFindings = Array.isArray(raw.findings) ? raw.findings : [];
  const findings: Finding[] = rawFindings
    .filter((f): f is Record<string, unknown> => f !== null && typeof f === "object")
    .map((f, i) =>
      sanitizeFinding(f, `f_${prefix}_${String(i + 1).padStart(2, "0")}`)
    );

  return { score, findings };
}

function buildDefaultVisionResult(): VisionAnalysisResult {
  const defaultPillar = { score: 50, findings: [] };
  return {
    visual_hierarchy: defaultPillar,
    cta_effectiveness: defaultPillar,
    trust_signals: defaultPillar,
    mobile_experience: defaultPillar,
  };
}

function buildDefaultTextResult(): TextAnalysisResult {
  const defaultPillar = { score: 50, findings: [] };
  return {
    value_proposition: defaultPillar,
    content_copy: defaultPillar,
  };
}

// ── HTML Utilities ────────────────────────────────────────────

function stripTags(html: string): string {
  return html.replace(/<[^>]+>/g, " ").replace(/&nbsp;/g, " ").trim();
}

function decodeHtmlEntities(text: string): string {
  return text
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#039;/g, "'")
    .replace(/&apos;/g, "'");
}

