async function runVisionAnalysis(
  screenshotBase64: string,
  pageType: PageType,
): Promise<VisionAnalysisResult> {
  const anthropicKey = Deno.env.get("ANTHROPIC_API_KEY");
  if (!anthropicKey) throw new Error("ANTHROPIC_API_KEY is not configured");

  const systemPrompt = buildVisionPrompt(pageType);

  const messageContent: unknown[] = screenshotBase64
    ? [
        {
          type: "image",
          source: {
            type: "base64",
            media_type: "image/jpeg",
            data: screenshotBase64,
          },
        },
        {
          type: "text",
          text: "Analyze this page screenshot and return the CRO analysis JSON.",
        },
      ]
    : [
        {
          type: "text",
          text: "No screenshot was available. Return JSON with score 50 for all pillars and findings noting that a screenshot could not be captured for visual analysis.",
        },
      ];

  const res = await fetch("https://api.anthropic.com/v1/messages", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "x-api-key": anthropicKey,
      "anthropic-version": "2023-06-01",
    },
    body: JSON.stringify({
      model: "claude-sonnet-4-20250514",
      max_tokens: 4096,
      system: systemPrompt,
      messages: [{ role: "user", content: messageContent }],
    }),
  });

  if (!res.ok) {
    const text = await res.text();
    throw new Error(`Anthropic API error ${res.status}: ${text.slice(0, 300)}`);
  }

  const data = await res.json();
  const rawText: string = data.content?.[0]?.text ?? "{}";

  return parseAndSanitizeVisionResult(rawText);
}

