// ── PageSpeed Analysis ────────────────────────────────────────

async function runPageSpeedAnalysis(url: string): Promise<PageSpeedResult> {
  const apiKey = Deno.env.get("PAGESPEED_API_KEY");
  if (!apiKey) {
    console.warn("PAGESPEED_API_KEY not set — using fallback performance score");
    return buildPageSpeedFallback();
  }

  // Call the pagespeed edge function via internal Supabase function invocation
  // Alternatively, call the Google API directly here
  const psUrl = new URL("https://www.googleapis.com/pagespeedonline/v5/runPagespeed");
  psUrl.searchParams.set("url", url);
  psUrl.searchParams.set("key", apiKey);
  psUrl.searchParams.set("strategy", "mobile");
  psUrl.searchParams.set("category", "performance");

  const res = await fetch(psUrl.toString(), {
    signal: AbortSignal.timeout(30_000),
  });

  if (!res.ok) {
    const text = await res.text();
    throw new Error(`PageSpeed API error ${res.status}: ${text.slice(0, 200)}`);
  }

  const psData = await res.json();
  return parsePageSpeedData(psData);
}

interface LighthouseResult {
  audits?: Record<string, { numericValue?: number; score?: number; displayValue?: string }>;
  categories?: Record<string, { score?: number }>;
}

function parsePageSpeedData(psData: Record<string, unknown>): PageSpeedResult {
  const lh = (psData as { lighthouseResult?: LighthouseResult })?.lighthouseResult;
  const audits = lh?.audits ?? {};
  const categories = lh?.categories ?? {};

  const performanceScore = Math.round(
    (categories.performance?.score ?? 0.5) * 100,
  );

  // Extract Core Web Vitals in milliseconds
  const lcpMs: number = audits["largest-contentful-paint"]?.numericValue ?? 0;
  const clsVal: number = audits["cumulative-layout-shift"]?.numericValue ?? 0;
  const tbtMs: number = audits["total-blocking-time"]?.numericValue ?? 0;
  const fcpMs: number = audits["first-contentful-paint"]?.numericValue ?? 0;
  const ttfbMs: number = audits["server-response-time"]?.numericValue ?? 0;
  const speedIndexMs: number = audits["speed-index"]?.numericValue ?? 0;

  const findings: Finding[] = [];

  // LCP findings
  if (lcpMs > 0) {
    const lcpSec = (lcpMs / 1000).toFixed(1);
    if (lcpMs > 4000) {
      findings.push(buildPerfFinding(
        "f_pp_lcp",
        `LCP (Largest Contentful Paint) is critically slow at ${lcpSec}s`,
        "critical",
        `Your LCP is ${lcpSec}s — Google classifies anything above 4.0s as 'Poor'. This is the single biggest drag on both your SEO rankings and conversion rate. Users see a blank/incomplete page for ${lcpSec} seconds before your primary content renders.`,
        "Identify your LCP element (usually the hero image). Serve it in WebP format, use <link rel='preload'> in <head>, and ensure it's not blocked by render-blocking resources.",
        `1. Add <link rel="preload" as="image" href="hero.webp"> to <head>\n2. Convert hero to WebP (60-80% smaller than PNG/JPG)\n3. Set explicit width/height on the hero element to prevent layout shift\n4. Remove any render-blocking CSS above the fold`,
        false,
        "moderate",
        "2-5% conversion lift",
        "Technical",
      ));
    } else if (lcpMs > 2500) {
      findings.push(buildPerfFinding(
        "f_pp_lcp",
        `LCP needs improvement at ${lcpSec}s (good threshold: 2.5s)`,
        "warning",
        `Your LCP is ${lcpSec}s — Google's 'Needs Improvement' range is 2.5-4.0s. Your hero content takes ${lcpSec} seconds to appear, which increases bounce rate by approximately ${Math.round((lcpMs - 2500) / 100)}%.`,
        "Optimize your LCP element: convert to WebP, add preload hint, and eliminate render-blocking resources above the fold.",
        `Add to <head>: <link rel="preload" as="image" href="hero.webp">\nConvert hero image to WebP format — typical savings: 60-80% file size reduction`,
        false,
        "moderate",
        "1-2% conversion lift",
        "Technical",
      ));
    } else {
      findings.push(buildPerfFinding(
        "f_pp_lcp",
        `Good LCP score: ${lcpSec}s (under 2.5s threshold)`,
        "passed",
        `Your LCP of ${lcpSec}s is within Google's 'Good' range (< 2.5s). Primary content renders quickly, minimizing abandonment from slow loads.`,
        "Maintain this performance. Monitor after adding new hero images or scripts.",
        "No changes needed — LCP is performing well.",
        false,
        "quick",
        "0%",
        "Technical",
      ));
    }
  }

  // CLS findings
  if (clsVal > 0) {
    if (clsVal > 0.25) {
      findings.push(buildPerfFinding(
        "f_pp_cls",
        `CLS (Cumulative Layout Shift) is critically high at ${clsVal.toFixed(3)}`,
        "critical",
        `Your CLS of ${clsVal.toFixed(3)} is in the 'Poor' range (Google threshold: > 0.25). Elements are jumping around visually as the page loads — this is one of the most frustrating user experiences and directly causes mis-clicks on buttons.`,
        "Add explicit width and height attributes to all images and iframes. Reserve space for dynamically injected content (ads, embeds, fonts).",
        `1. Add width/height to all images: <img width="800" height="450" ...>\n2. Add font-display: swap to @font-face declarations\n3. Reserve space for ads: min-height: 250px on ad containers\n4. Avoid inserting content above existing content on page load`,
        false,
        "moderate",
        "1-3% conversion lift",
        "Technical",
      ));
    } else if (clsVal > 0.1) {
      findings.push(buildPerfFinding(
        "f_pp_cls",
        `CLS score needs improvement at ${clsVal.toFixed(3)} (good threshold: 0.1)`,
        "warning",
        `Your CLS of ${clsVal.toFixed(3)} is in the 'Needs Improvement' range. Some elements are shifting during page load — likely images without dimensions or late-loading fonts.`,
        "Add explicit dimensions to images and use font-display: swap to prevent invisible text flashes.",
        `Add width/height attributes to images above the fold. For fonts: add font-display: swap to your @font-face rules.`,
        false,
        "quick",
        "0.5-1% conversion lift",
        "Technical",
      ));
    } else {
      findings.push(buildPerfFinding(
        "f_pp_cls",
        `Good CLS score: ${clsVal.toFixed(3)} (under 0.1 threshold)`,
        "passed",
        `Your CLS of ${clsVal.toFixed(3)} is within Google's 'Good' range. Page elements stay stable during load — no jarring visual jumps.`,
        "Continue setting explicit dimensions on images and reserving space for dynamic content.",
        "No changes needed — layout stability is excellent.",
        false,
        "quick",
        "0%",
        "Technical",
      ));
    }
  }

  // TBT (proxy for FID/INP) findings
  if (tbtMs > 0) {
    if (tbtMs > 600) {
      findings.push(buildPerfFinding(
        "f_pp_tbt",
        `Total Blocking Time is critically high at ${Math.round(tbtMs)}ms`,
        "critical",
        `Your TBT is ${Math.round(tbtMs)}ms — well above Google's 200ms good threshold. The main thread is blocked for over half a second during load, making the page feel unresponsive. Users who click buttons during this window get no response, causing frustration and abandonment.`,
        "Audit your JavaScript bundles. Remove unused code, defer non-critical scripts, and break up long tasks (>50ms) into smaller chunks.",
        `1. Run: npx bundlesize to identify large bundles\n2. Add defer/async to non-critical scripts\n3. Use dynamic import() for below-fold components\n4. Remove unused JavaScript with tree-shaking\nTarget: get TBT under 200ms`,
        true,
        "significant",
        "1-3% conversion lift",
        "Technical",
      ));
    } else if (tbtMs > 200) {
      findings.push(buildPerfFinding(
        "f_pp_tbt",
        `Total Blocking Time needs improvement at ${Math.round(tbtMs)}ms`,
        "warning",
        `Your TBT of ${Math.round(tbtMs)}ms is in the 'Needs Improvement' range (good: < 200ms). JavaScript is blocking the main thread longer than optimal.`,
        "Defer non-critical third-party scripts and audit your JavaScript for unused code.",
        `Add defer attribute to analytics and chat scripts. Load third-party widgets only after user interaction (first scroll or click).`,
        false,
        "moderate",
        "0.5-1% conversion lift",
        "Technical",
      ));
    }
  }

  // TTFB findings
  if (ttfbMs > 800) {
    findings.push(buildPerfFinding(
      "f_pp_ttfb",
      `Server response time (TTFB) is slow at ${Math.round(ttfbMs)}ms`,
      ttfbMs > 1800 ? "critical" : "warning",
      `Time to First Byte is ${Math.round(ttfbMs)}ms — Google's good threshold is 800ms. Your server takes ${(ttfbMs / 1000).toFixed(1)} seconds just to start sending data. This delays everything downstream.`,
      "Use a CDN (Cloudflare, Vercel Edge) to serve cached responses closer to users. Optimize server-side rendering or database queries if TTFB is high on all pages.",
      `1. Enable Cloudflare or Vercel Edge Caching\n2. Set Cache-Control headers: max-age=3600 for static assets\n3. If on a shared host, upgrade to dedicated or CDN-backed infrastructure\n4. Run EXPLAIN ANALYZE on slow DB queries`,
      true,
      "significant",
      "1-2% conversion lift",
      "Technical",
    ));
  }

  // Speed Index
  if (speedIndexMs > 3400) {
    findings.push(buildPerfFinding(
      "f_pp_si",
      `Speed Index is high at ${(speedIndexMs / 1000).toFixed(1)}s — page feels slow to fill`,
      "warning",
      `Speed Index of ${(speedIndexMs / 1000).toFixed(1)}s measures how quickly content is visually complete. Above 3.4s means users see a partially empty page for an extended period, which signals poor quality.`,
      "Prioritize above-the-fold content rendering. Use SSR or SSG where possible, and eliminate render-blocking resources.",
      `Use critical CSS inlining for above-fold styles. Remove render-blocking fonts with font-display: swap. Aim for Speed Index under 3.4s.`,
      true,
      "moderate",
      "0.5-1% conversion lift",
      "Technical",
    ));
  }

  // If we have few findings, pad with a general performance note
  if (findings.length < 2) {
    findings.push(buildPerfFinding(
      "f_pp_gen",
      "Page performance is within acceptable range",
      "info",
      `Overall PageSpeed score is ${performanceScore}/100. Core Web Vitals are within acceptable ranges for most users.`,
      "Continue monitoring performance as you add new features. Run Lighthouse audits monthly.",
      "Set up automated Lighthouse CI to catch performance regressions in your deployment pipeline.",
      false,
      "quick",
      "0%",
      "Technical",
    ));
  }

  return { score: performanceScore, findings };
}

function buildPerfFinding(
  id: string,
  title: string,
  severity: "critical" | "warning" | "info" | "passed",
  current_state: string,
  recommendation: string,
  ai_suggestion: string,
  is_premium: boolean,
  effort: "quick" | "moderate" | "significant",
  estimated_lift: string,
  category: string,
): Finding {
  return {
    id,
    title,
    severity,
    current_state,
    recommendation,
    ai_suggestion,
    is_premium,
    effort,
    estimated_lift,
    category,
  };
}

function buildPageSpeedFallback(): PageSpeedResult {
  return {
    score: 65,
    findings: [
      buildPerfFinding(
        "f_pp_fallback",
        "PageSpeed data unavailable — using estimated score",
        "info",
        "Google PageSpeed Insights API was not available during this scan. Performance score is estimated at 65/100 (industry average).",
        "Configure PAGESPEED_API_KEY to enable real PageSpeed analysis in future scans.",
        "Add your Google Cloud API key as PAGESPEED_API_KEY in Supabase Edge Function secrets.",
        false,
        "quick",
        "0%",
        "Technical",
      ),
    ],
  };
}

// ── AI Response Parsers ───────────────────────────────────────

function extractJsonFromText(text: string): string {
  // Strip markdown code blocks if present
  const codeBlockMatch = text.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (codeBlockMatch) return codeBlockMatch[1].trim();

  // Find first { and last }
  const start = text.indexOf("{");
  const end = text.lastIndexOf("}");
  if (start !== -1 && end !== -1 && end > start) {
    return text.slice(start, end + 1);
  }

  return text.trim();
}

function parseAndSanitizeVisionResult(rawText: string): VisionAnalysisResult {
  let parsed: Record<string, unknown>;
  try {
    parsed = JSON.parse(extractJsonFromText(rawText));
  } catch (_e) {
    console.error("Failed to parse vision AI response:", rawText.slice(0, 500));
    // Return safe defaults
    return buildDefaultVisionResult();
  }

  return {
    visual_hierarchy: sanitizePillarResult(
      parsed.visual_hierarchy as Record<string, unknown>,
      "vh",
    ),
    cta_effectiveness: sanitizePillarResult(
      parsed.cta_effectiveness as Record<string, unknown>,
      "ct",
    ),
    trust_signals: sanitizePillarResult(
      parsed.trust_signals as Record<string, unknown>,
      "ts",
    ),
    mobile_experience: sanitizePillarResult(
      parsed.mobile_experience as Record<string, unknown>,
      "me",
    ),
  };
}

function parseAndSanitizeTextResult(rawText: string): TextAnalysisResult {
  let parsed: Record<string, unknown>;
  try {
    parsed = JSON.parse(extractJsonFromText(rawText));
  } catch (_e) {
    console.error("Failed to parse text AI response:", rawText.slice(0, 500));
    return buildDefaultTextResult();
  }

  return {
    value_proposition: sanitizePillarResult(
      parsed.value_proposition as Record<string, unknown>,
      "vp",
    ),
    content_copy: sanitizePillarResult(
      parsed.content_copy as Record<string, unknown>,
      "cc",
    ),
    cta_effectiveness: parsed.cta_effectiveness
      ? sanitizePillarResult(
          parsed.cta_effectiveness as Record<string, unknown>,
          "ct_copy",
        )
      : undefined,
  };
}

function sanitizePillarResult(
  raw: Record<string, unknown> | undefined,
  prefix: string,
): { score: number; findings: Finding[] } {
  if (!raw || typeof raw !== "object") {
    return { score: 50, findings: [] };
  }

  const score = typeof raw.score === "number"
    ? Math.max(0, Math.min(100, Math.round(raw.score)))
    : 50;

  const rawFindings = Array.isArray(raw.findings) ? raw.findings : [];
  const findings: Finding[] = rawFindings
    .filter((f): f is Record<string, unknown> => f !== null && typeof f === "object")
    .map((f, i) =>
      sanitizeFinding(f, `f_${prefix}_${String(i + 1).padStart(2, "0")}`)
    );

  return { score, findings };
}

function buildDefaultVisionResult(): VisionAnalysisResult {
  const defaultPillar = { score: 50, findings: [] };
  return {
    visual_hierarchy: defaultPillar,
    cta_effectiveness: defaultPillar,
    trust_signals: defaultPillar,
    mobile_experience: defaultPillar,
  };
}

function buildDefaultTextResult(): TextAnalysisResult {
  const defaultPillar = { score: 50, findings: [] };
  return {
    value_proposition: defaultPillar,
    content_copy: defaultPillar,
  };
}

// ── HTML Utilities ────────────────────────────────────────────

function stripTags(html: string): string {
  return html.replace(/<[^>]+>/g, " ").replace(/&nbsp;/g, " ").trim();
}

function decodeHtmlEntities(text: string): string {
  return text
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#039;/g, "'")
    .replace(/&apos;/g, "'");
}

/**
 * send-email — Edge Function
 *
 * Sends transactional emails via Resend (HTTP, no SDK — Deno compatible).
 *
 * Accepted request body shapes:
 *   { type: 'welcome';        to: string; data: { name: string } }
 *   { type: 'scan_complete';  to: string; data: { name: string; url: string; score: number; scan_id: string; critical_count: number; quick_wins: number } }
 *   { type: 'weekly_digest';  to: string; data: { name: string; scans_this_week: number; avg_score: number } }
 *
 * Required env vars:
 *   RESEND_API_KEY — Resend secret key
 *   APP_URL        — e.g. https://app.convertscan.com (no trailing slash)
 */

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";

// ── CORS ──────────────────────────────────────────────────────────

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

function jsonResponse(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
}

