// ── Request types ─────────────────────────────────────────────────

type EmailRequest =
  | { type: "welcome"; to: string; data: WelcomeData }
  | { type: "scan_complete"; to: string; data: ScanCompleteData }
  | { type: "weekly_digest"; to: string; data: WeeklyDigestData };

// ── Resend call ───────────────────────────────────────────────────

async function sendViaResend(
  to: string,
  subject: string,
  html: string,
): Promise<void> {
  const apiKey = Deno.env.get("RESEND_API_KEY");
  if (!apiKey) {
    throw new Error("RESEND_API_KEY env var is not set");
  }

  const res = await fetch("https://api.resend.com/emails", {
    method: "POST",
    headers: {
      "Authorization": `Bearer ${apiKey}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      from: FROM_ADDRESS,
      to,
      subject,
      html,
    }),
  });

  if (!res.ok) {
    const body = await res.text();
    throw new Error(`Resend API error ${res.status}: ${body.slice(0, 300)}`);
  }
}

// ── Main handler ──────────────────────────────────────────────────

serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  if (req.method !== "POST") {
    return jsonResponse({ error: "Method not allowed" }, 405);
  }

  const appUrl = Deno.env.get("APP_URL") ?? "https://app.convertscan.com";

  let payload: EmailRequest;
  try {
    payload = await req.json() as EmailRequest;
  } catch {
    return jsonResponse({ error: "Invalid JSON body" }, 400);
  }

  if (!payload.type || !payload.to) {
    return jsonResponse({ error: "type and to are required" }, 400);
  }

  let subject: string;
  let html: string;

  try {
    switch (payload.type) {
      case "welcome": {
        const result = buildWelcomeEmail(payload.to, payload.data, appUrl);
        subject = result.subject;
        html = result.html;
        break;
      }
      case "scan_complete": {
        const result = buildScanCompleteEmail(payload.to, payload.data, appUrl);
        subject = result.subject;
        html = result.html;
        break;
      }
      case "weekly_digest": {
        const result = buildWeeklyDigestEmail(payload.to, payload.data, appUrl);
        subject = result.subject;
        html = result.html;
        break;
      }
      default: {
        return jsonResponse({ error: `Unknown email type: ${(payload as { type: string }).type}` }, 400);
      }
    }
  } catch (err) {
    console.error("Email template build failed:", err);
    return jsonResponse({ error: "Failed to build email template" }, 500);
  }

  try {
    await sendViaResend(payload.to, subject, html);
    return jsonResponse({ status: "sent", type: payload.type, to: payload.to });
  } catch (err) {
    console.error("Resend delivery failed:", err);
    return jsonResponse(
      { error: "Email delivery failed", detail: err instanceof Error ? err.message : "unknown" },
      500,
    );
  }
});

